-- Step 1 LOB sizes, the source: generated by the modernizer; you run it, it never connects to your databases.
-- Step contract SHA-256: 7eb935f5826c52d8da86f092e1f815095a6ab4355f3ac487c5520b5795f40a46
-- Read-only: one SELECT per table, each in a READ ONLY transaction. 16 tables, 20 LOB columns; each table is read in full (a full scan).
-- It prints the longest value's length in bytes and the non-NULL count per column, never a value. See lob-sizes.md.
SET NAMES utf8mb4;
SET SESSION TRANSACTION READ ONLY;
SELECT 'modernizer-lob-sizes', '1', '7eb935f5826c52d8da86f092e1f815095a6ab4355f3ac487c5520b5795f40a46', '88b8692c7bae8cb4e5889a39a6e9fcff9e37e03642b22e616f1adc313134dabe', DATE_FORMAT(UTC_TIMESTAMP(6), '%Y-%m-%dT%H:%i:%s.%f');
-- 1: wordpress.wp_actionscheduler_actions
START TRANSACTION READ ONLY;
SELECT 'column', '1', p.k, CAST(COALESCE(CASE p.k WHEN '1' THEN m.m1 END, 0) AS CHAR), CAST(CASE p.k WHEN '1' THEN m.v1 END AS CHAR)
FROM (SELECT MAX(LENGTH(`schedule`)) AS m1, COUNT(`schedule`) AS v1 FROM `wordpress`.`wp_actionscheduler_actions`) AS m CROSS JOIN (SELECT '1' AS k) AS p ORDER BY p.k + 0;
COMMIT;
